 * The tree the parser builds. Every node carries the type name the `keys` mode
 * prints, so a table is `table`, an array of tables is an `array` like any
 * other, and the numbers keep the distinction between `integer` and `float`.
 */

export function newTable(defined = false) {
  return { t: 'table', map: new Map(), defined }
}

export function newArray(tables = false) {
  return { t: 'array', items: [], tables }
}

export function scalar(t, v) {
  return { t, v }
}

export function isTableArray(node) {
  return node !== undefined && node.t === 'array' && node.tables
}

/** Compare two key strings by code point, ascending. */
export function compareKeys(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const p = x[i].codePointAt(0)
    const q = y[i].codePointAt(0)
    if (p !== q) return p < q ? -1 : 1
  }
  if (x.length === y.length) return 0
  return x.length < y.length ? -1 : 1
}

export function sortedKeys(table) {
  return Array.from(table.map.keys()).sort(compareKeys)
}
"}

