{"file_path":"src/parse.js","content":"/**
 * The configuration parser. Each line stands on its own, so a cursor over the
 * text of one line carries every scanning routine, and the document walker
 * keeps the current table the headers select.
 */

import { ConfError } from './errors.js'
import { newTable, newArray, scalar, isTableArray } from './nodes.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const DIGITS = '[0-9]+(?:_[0-9]+)*'
const INTEGER = new RegExp(`^[+-]?${DIGITS}$`)
const NUMBER = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`)

/** The characters that close a value without belonging to it. */
const VALUE_STOP = new Set([' ', '\t', ',', ']', '}', ';'])

class Cursor {
  constructor(text, line) {
    this.s = text
    this.n = text.length
    this.i = 0
    this.line = line
  }

  fail(reason) {
    throw new ConfError(this.line, reason)
  }

  /** The character under the cursor, or null past the end of the line. */
  peek() {
    return this.i < this.n ? this.s[this.i] : null
  }

  skipBlanks() {
    while (this.i < this.n && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /** True where the line is spent, a comment counting as the end of it. */
  done() {
    if (this.i >= this.n) return true
    const c = this.s[this.i]
    return c === '#' || c === ';'
  }

  // --- strings -----------------------------------------------------------

  string() {
    const quote = this.s[this.i]
    this.i++
    if (quote === "'") {
      const start = this.i
      while (this.i < this.n && this.s[this.i] !== "'") this.i++
      if (this.i >= this.n) this.fail('unterminated string')
      const text = this.s.slice(start, this.i)
      this.i++
      return text
    }
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = this.s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c !== '\\') {
        out += c
        this.i++
        continue
      }
      this.i++
      if (this.i >= this.n) this.fail('unterminated string')
      const e = this.s[this.i]
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const hex = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(hex)) this.fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(hex, 16))
        this.i += 4
      } else this.fail(`invalid escape \\${e}`)
    }
  }

  // --- names -------------------------------------------------------------

  name() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.string()
    const start = this.i
    while (this.i < this.n && NAME_CHAR.test(this.s[this.i])) this.i++
    if (this.i === start) this.fail('expected a name')
    return this.s.slice(start, this.i)
  }

  /** A dotted name, with spaces and tabs allowed around each dot. */
  dottedName() {
    const parts = [this.name()]
    for (;;) {
      const mark = this.i
      this.skipBlanks()
      if (this.peek() !== '.') {
        this.i = mark
        return parts
      }
      this.i++
      this.skipBlanks()
      parts.push(this.name())
    }
  }

  // --- values ------------------------------------------------------------

  value(path) {
    const c = this.peek()
    if (c === null || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') {
      this.fail('expected a value')
    }
    if (c === '"' || c === "'") return scalar('string', this.string())
    if (c === '[') return this.array(path)
    if (c === '{') return this.inlineTable(path)
    const start = this.i
    while (this.i < this.n && !VALUE_STOP.has(this.s[this.i])) this.i++
    return this.bareValue(this.s.slice(start, this.i))
  }

  bareValue(text) {
    if (text === 'true') return scalar('boolean', true)
    if (text === 'false') return scalar('boolean', false)
    if (INTEGER.test(text)) return scalar('integer', Number(text.replace(/_/g, '')))
    if (NUMBER.test(text)) return scalar('float', Number(text.replace(/_/g, '')))
    this.fail(`invalid value ${text}`)
  }

  array(path) {
    this.i++
    const node = newArray(false)
    for (;;) {
      this.skipBlanks()
      if (this.done()) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.i++
        return node
      }
      node.items.push(this.value(path))
      this.skipBlanks()
      if (this.done()) this.fail('unterminated array')
      const c = this.peek()
      if (c === ',') {
        this.i++
        continue
      }
      if (c === ']') {
        this.i++
        return node
      }
      this.fail('unterminated array')
    }
  }

  inlineTable(path) {
    this.i++
    const table = newTable(false)
    this.skipBlanks()
    if (this.done()) this.fail('unterminated inline table')
    if (this.peek() === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.skipBlanks()
      if (this.done()) this.fail('unterminated inline table')
      const key = this.dottedName()
      this.skipBlanks()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i++
      this.skipBlanks()
      const value = this.value(path.concat(key))
      assign(table, key, value, path, this)
      this.skipBlanks()
      if (this.done()) this.fail('unterminated inline table')
      const c = this.peek()
      if (c === ',') {
        this.i++
        continue
      }
      if (c === '}') {
        this.i++
        return table
      }
      this.fail('unterminated inline table')
    }
  }
}

/** Walk the dots of a key, creating the tables they pass through. */
function walkKey(table, parts, base, cursor) {
  let current = table
  const path = base.slice()
  for (let k = 0; k < parts.length - 1; k++) {
    path.push(parts[k])
    const next = current.map.get(parts[k])
    if (next === undefined) {
      const made = newTable(false)
      current.map.set(parts[k], made)
      current = made
    } else if (next.t === 'table') {
      current = next
    } else if (isTableArray(next) && next.items.length > 0) {
      current = next.items[next.items.length - 1]
    } else {
      cursor.fail(`${path.join('.')} is not a table`)
    }
  }
  return { table: current, path }
}

function assign(table, parts, value, base, cursor) {
  const { table: owner, path } = walkKey(table, parts, base, cursor)
  const last = parts[parts.length - 1]
  path.push(last)
  if (owner.map.has(last)) cursor.fail(`key ${path.join('.')} is defined twice`)
  owner.map.set(last, value)
}

function header(cursor, state) {
  cursor.i++
  let doubled = false
  if (cursor.peek() === '[') {
    doubled = true
    cursor.i++
  }
  cursor.skipBlanks()
  const parts = cursor.dottedName()
  cursor.skipBlanks()
  if (cursor.peek() !== ']') cursor.fail('unterminated table header')
  cursor.i++
  if (doubled) {
    if (cursor.peek() !== ']') cursor.fail('unterminated table header')
    cursor.i++
  }
  cursor.skipBlanks()
  if (!cursor.done()) cursor.fail('trailing text after a table header')

  const { table: owner, path } = walkKey(state.root, parts, [], cursor)
  const last = parts[parts.length - 1]
  path.push(last)
  const existing = owner.map.get(last)
  if (!doubled) {
    let table = existing
    if (table === undefined) {
      table = newTable(false)
      owner.map.set(last, table)
    } else if (table.t !== 'table') {
      cursor.fail(`${path.join('.')} is not a table`)
    } else if (table.defined) {
      cursor.fail(`table ${path.join('.')} is defined twice`)
    }
    table.defined = true
    state.current = table
  } else {
    let array = existing
    if (array === undefined) {
      array = newArray(true)
      owner.map.set(last, array)
    } else if (!isTableArray(array)) {
      cursor.fail(`${path.join('.')} is not an array of tables`)
    }
    const element = newTable(true)
    array.items.push(element)
    state.current = element
  }
  state.path = path
}

function keyValue(cursor, state) {
  const parts = cursor.dottedName()
  cursor.skipBlanks()
  if (cursor.peek() !== '=') cursor.fail('expected key = value')
  cursor.i++
  cursor.skipBlanks()
  const value = cursor.value(state.path.concat(parts))
  cursor.skipBlanks()
  if (!cursor.done()) cursor.fail('trailing text after a value')
  assign(state.current, parts, value, state.path, cursor)
}

/** Split the document the way the specification asks. */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function parseDocument(text) {
  const root = newTable(true)
  const state = { root, current: root, path: [] }
  const lines = splitLines(text)
  for (let n = 0; n < lines.length; n++) {
    const cursor = new Cursor(lines[n], n + 1)
    cursor.skipBlanks()
    if (cursor.done()) continue
    if (cursor.peek() === '[') header(cursor, state)
    else keyValue(cursor, state)
  }
  return root
}
"}

