/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { ConfError } from './errors.js'
import { parseDocument } from './parse.js'
import { toJson, toKeys } from './render.js'

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'json' && mode !== 'keys')) {
    die('usage: cli.js json|keys')
  }
  let output
  try {
    const root = parseDocument(readStdin())
    output = mode === 'json' ? toJson(root) : toKeys(root)
  } catch (error) {
    if (error instanceof ConfError) die(`line ${error.line}: ${error.reason}`)
    throw error
  }
  process.stdout.write(output)
}

main(process.argv.slice(2))
"}

